// Streams the upload straight to storage, so memory use is bounded
// rather than scaling with the upload size. This relies on
// blobstore-sdk >= 2.4, which added the streaming putObjectStream API;
// earlier 1.x only accepted a fully buffered Buffer.
async function upload(io, stream) {
  return io.putObjectStream(stream);
}

